func (b *gormBatch) UpdateAllocationOutputOnly(in *allocationpbv1.Allocation, paths []string) {
	r := &GormAllocationRepository{DB: b.db}
	b.u.QueueGorm(nil, func(ctx context.Context, tx *gorm.DB) error {
		return r.updateOutputOnlyTx(ctx, tx, in, paths)
	})
	b.u.Record(repox.Change{Type: "freebusy.allocation.v1/Allocation", Name: in.GetName(), Op: repox.ChangeUpdate, Record: in, LoadPrior: repox.PriorOf(in.GetName(), getAllocation)})
}

// DeleteAllocation queues the record's removal for good. A record already
// gone is not an error: two batches clearing the same row must not fail each
// other.
func (b *gormBatch) DeleteAllocation(name string) {
	r := &GormAllocationRepository{DB: b.db}
	key, err := r.rowKey(name)
	if err != nil {
		b.u.Fail(err)
		return
	}
	queueAllocationDelete(b.u, name, true)
	b.u.QueueGorm(nil, func(ctx context.Context, tx *gorm.DB) error {
		return tx.WithContext(ctx).Delete(&allocation.Allocation{}, "name = ?", key).Error
	})
	b.u.Record(repox.Change{Type: "freebusy.allocation.v1/Allocation", Name: name, Op: repox.ChangeDelete, LoadPrior: repox.PriorOf(name, getAllocation)})
}

